// deno-lint-ignore-file no-explicit-any
import type { SupabaseClient } from 'https://esm.sh/@supabase/supabase-js@2.117.2';
// @ts-ignore generated by build:edge-shared (resolved at deploy)
import { entitlementsForPlan, MockFlightProvider, redactDeal } from './core.mjs';

/** Provider factory — the ONLY place a concrete provider is chosen. API keys stay server-side. */
export function getProvider(): any {
  const name = Deno.env.get('FLIGHT_PROVIDER') ?? 'mock';
  if (name === 'mock') return new MockFlightProvider();
  throw new Error(`Flight provider "${name}" is not implemented yet. Add an adapter implementing FlightProvider.`);
}

/** Price history: our own private.price_snapshots first; deterministic mock history only when the backend is still empty AND provider=mock. */
export async function loadHistory(sb: SupabaseClient, provider: any, identity: string, minPoints = 12) {
  const { data } = await sb.schema('private').from('price_snapshots').select('captured_at, price, provider').eq('flight_identity', identity).order('captured_at', { ascending: true }).limit(500);
  const rows = (data ?? []).map((r: any) => ({ capturedAt: r.captured_at, price: Number(r.price), provider: r.provider }));
  if (rows.length >= minPoints || typeof provider.getHistory !== 'function') return rows;
  return provider.getHistory(identity);
}

export async function recordOffer(sb: SupabaseClient, deal: any) {
  const o = deal.offer, a = deal.analysis;
  await sb.schema('private').from('price_snapshots').insert({
    route: `${o.origin}-${o.destination}`, flight_identity: o.flightIdentity, provider: o.provider, carrier: o.carrier,
    departure_date: o.departureAt.slice(0, 10), cabin: o.cabin, price: o.price.amount, currency: o.price.currency,
    captured_at: o.capturedAt, availability_state: o.availability, offer_expiry: o.expiresAt,
  });
  await sb.schema('private').from('flight_offers').upsert({
    id: o.id, provider: o.provider, provider_offer_id: o.providerOfferId, flight_identity: o.flightIdentity, carrier: o.carrier, origin: o.origin, destination: o.destination,
    departure_at: o.departureAt, cabin: o.cabin, stops: o.stops, duration_minutes: o.durationMinutes, last_price: o.price.amount, currency: o.price.currency, availability: o.availability, offer_expiry: o.expiresAt, updated_at: new Date().toISOString(),
  });
  await sb.schema('private').from('anomaly_results').insert({ offer_id: o.id, score: a.anomaly.score, level: a.anomaly.level, components: a.anomaly.components });
  await sb.schema('private').from('forecasts').insert({ offer_id: o.id, model_version: a.forecast.modelVersion, result: a.forecast });
  await sb.schema('private').from('recommendations').insert({
    offer_id: o.id, flight_identity: o.flightIdentity, price: o.price.amount, decision: a.decision.decision, reasons: a.decision.reasons,
    prediction: a.forecast, confidence: a.decision.confidence, model_version: a.forecast.modelVersion,
  });
}

export async function cost(sb: SupabaseClient, e: { provider: string; operation: string; estimated_cost?: number; tokens?: number; request_count?: number; user_id?: string; deal_id?: string }) {
  await sb.schema('private').from('cost_events').insert({ estimated_cost: 0, request_count: 1, ...e });
}
export async function providerLog(sb: SupabaseClient, provider: string, operation: string, ok: boolean, latency: number, error?: string) {
  await sb.schema('private').from('provider_logs').insert({ provider, operation, ok, latency_ms: latency, error: error?.slice(0, 300) });
}
const planCache = new Map<string, { plan: string; at: number }>();
/** effective_plan() lookups are cached for 15s per instance so list responses cost one query, not one per deal. */
export async function planFor(sb: SupabaseClient, uid: string): Promise<string> {
  const hit = planCache.get(uid);
  if (hit && Date.now() - hit.at < 15_000) return hit.plan;
  const { data } = await sb.rpc('effective_plan', { uid });
  const plan = (data as string) ?? 'FREE';
  planCache.set(uid, { plan, at: Date.now() });
  return plan;
}

/** Enforce Advanced Forecast server-side: FREE callers never receive premium fields. */
export async function redactFor(sb: SupabaseClient, uid: string, deal: any) {
  return redactDeal(deal, entitlementsForPlan(await planFor(sb, uid)));
}
